namespace Commerz\Ports\Sellables\Contracts;

#[Api(since: '0.1')]
interface Sellables                                  // маршрутизатор по SellableRef::type → SellableProvider
{
    public function resolve(SellableRef $ref, CommerceContext $context): SellableSnapshot;   // SellableUnavailable
    /** @param list<SellableRef> $refs  @return array<string, SellableSnapshot> keyed by (string) $ref */
    public function resolveMany(array $refs, CommerceContext $context): array;
}

#[Spi(kind: SpiKind::Implement, since: '0.1')]
interface SellableProvider
{
    public function key(): string;                   // 'variant', 'crm.service'
    /** @param list<SellableRef> $refs  @return array<string, SellableSnapshot> */
    public function resolve(array $refs, CommerceContext $context): array;
}

final readonly class SellableSnapshot {
    public function __construct(
        public SellableRef $ref, public string $sku, public string $name,            // имя в локали контекста
        public SellableKind $kind,                    // Physical|Digital|Service
        public bool $requiresShipping, public bool $purchasable, public ?string $unavailableReason,
        /** @var array<string,string> */ public array $options = [],              // 'Цвет' => 'Красный'
        public ?Money $basePrice = null,              // цена провайдера (CRM); pricing её перекрывает
        public ?string $taxClass = null, public ?int $weightGrams = null,
        /** @var array<string,scalar> */ public array $attributes = [],            // для условий акций
        /** @var list<string> */ public array $categories = [],
    ) {}
}
```

